const slides = [
{section:"OUVERTURE",title:"MedLink DZ",kicker:"PROJET D’ENTREPRENEURIAT · UMMTO · 2026–2027",kind:"cover",content:`
<div class="cover-layout"><div><span class="tag">PROJET D’ENTREPRENEURIAT · UMMTO · 2026–2027</span><h1 class="cover-title">MedLink <span>DZ</span></h1><p class="cover-sub">Mieux coordonner le suivi des patients après une consultation ou une hospitalisation.</p><p class="lead">Une plateforme numérique qui relie le médecin et son patient autour d'un programme de suivi clair, validé et traçable.</p><div class="cover-foot"><span>UMMTO · Université Mouloud Mammeri de Tizi-Ouzou</span><span>Département informatique</span><span>2ᵉ année ingénieur</span><span>Année universitaire 2026–2027</span></div></div><div class="cover-visual"><div class="orb"><i class="orb-node n1"></i><i class="orb-node n2"></i><i class="orb-node n3"></i></div><div class="orb-core">M</div></div></div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Le parcours ne s'arrête pas à la sortie",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">LE CONSTAT</span><p class="big-quote" style="margin:14px 0 16px">« La consultation se termine. L'accompagnement, lui, continue. »</p><p>Après une hospitalisation, une intervention ou un traitement, le patient doit parfois suivre plusieurs prescriptions, surveiller son état, réaliser des analyses, prendre des rendez-vous et rester en contact avec son médecin.</p><p style="margin-top:12px">Entre deux consultations, il doit garder le fil de son parcours — parfois avec l'aide de ses proches.</p></div>
<div class="panel reveal"><div class="card-title">Un suivi qui se prolonge à domicile</div><div class="steps">
<div class="step"><div class="step-num">01</div><h3>Retour à domicile</h3><p>Retenir les consignes et organiser les premières étapes.</p></div>
<div class="step"><div class="step-num">02</div><h3>Période de traitement</h3><p>Respecter les prescriptions, examens et rendez-vous.</p></div>
<div class="step"><div class="step-num">03</div><h3>Entre deux consultations</h3><p>Signaler une difficulté et savoir qui contacter.</p></div>
<div class="step"><div class="step-num">04</div><h3>Surveillance</h3><p>Poursuivre les contrôles lorsqu'un suivi reste nécessaire.</p></div>
</div></div></div>
<div class="callout footnote">MedLink DZ vise à maintenir un lien organisé entre le patient, son médecin et, si celui-ci l'autorise, les membres de son équipe de suivi.</div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Trois difficultés qui se renforcent",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">PROBLÈME IDENTIFIÉ</span><h3>Une coordination difficile à maintenir à domicile</h3><p>Les actions du suivi — prescriptions, rendez-vous, examens, informations sur l'évolution et demandes d'aide — peuvent être réparties entre plusieurs supports et interlocuteurs.</p><div class="divider"></div><ul>
<li>Consignes réparties entre appels, messages et documents papier.</li>
<li>Patient incertain du professionnel à contacter.</li>
<li>Proches aidants manquant parfois de visibilité sur les étapes à accomplir.</li>
<li>Médecin ne recevant pas toujours facilement les informations utiles entre les consultations.</li>
<li>Recherche d'un professionnel ou d'une clinique disponible et proche parfois longue.</li>
</ul></div>
<div class="panel reveal"><span class="tag">CONTEXTE ALGÉRIEN</span><h3>Un problème à vérifier sur le terrain</h3><p>Le projet part d'une difficulté concrète d'organisation du suivi à domicile et de mise en relation. Il ne suppose ni que tous les patients rencontrent les mêmes obstacles, ni que le système de santé est dépourvu de suivi.</p><div class="divider"></div><p><b>Validation nécessaire :</b> confronter ces hypothèses aux expériences de patients, de familles, de médecins et de structures de santé.</p></div>
</div>
<div class="panel reveal" style="margin-top:13px"><span class="eyebrow">PROBLÉMATIQUE CENTRALE</span><p class="big-quote" style="margin:10px 0 0;font-size:clamp(17px,1.8vw,25px)">Comment assurer, en Algérie, un suivi médical plus continu et mieux coordonné à domicile, en facilitant les échanges avec le médecin sans remplacer son jugement médical ?</p></div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Qui est concerné par cette difficulté ?",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">CIBLE INITIALE À TESTER</span><h3>Patients nécessitant un suivi organisé</h3><p>Adultes qui rentrent à domicile après une hospitalisation ou une intervention, ou qui suivent un traitement nécessitant des étapes définies entre deux consultations.</p><div class="divider"></div><b class="accent">Situations prioritaires</b><ul><li>Suivi post-hospitalisation ou post-opératoire.</li><li>Suivi de maladies chroniques stabilisées, selon un protocole défini par le médecin.</li><li>Contrôles et examens planifiés après un traitement.</li></ul></div>
<div class="panel reveal"><span class="tag">UTILISATEURS SECONDAIRES</span><h3>Proches aidants</h3><p>Personnes autorisées par le patient à participer à l'organisation pratique de son parcours.</p><div class="divider"></div><ul><li>Aider à organiser les rendez-vous.</li><li>Suivre les rappels et les étapes prévues.</li><li>Contribuer aux échanges dans les limites des accès accordés.</li></ul></div>
<div class="panel reveal"><span class="tag">CLIENTS ET PARTENAIRES</span><h3>Professionnels et structures</h3><p>Les médecins constituent le payeur principal envisagé ; les cabinets et cliniques peuvent devenir des partenaires de déploiement.</p><div class="divider"></div><ul><li>Médecins traitants et spécialistes.</li><li>Cabinets et cliniques.</li><li>Professionnels intervenant dans le suivi à domicile.</li></ul></div>
</div><div class="callout footnote">Le MVP doit commencer par un parcours et une population clairement délimités. Les proches n'accèdent aux informations qu'avec une autorisation appropriée.</div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Les besoins fonctionnels qui découlent du problème",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">ORGANISER</span><h3>Rendre le parcours lisible</h3><ul><li>Regrouper les consignes validées.</li><li>Afficher les tâches et échéances.</li><li>Retrouver les rendez-vous et les demandes.</li><li>Conserver un historique des échanges utiles.</li></ul></div>
<div class="panel reveal"><span class="tag">ACCOMPAGNER</span><h3>Faciliter le suivi quotidien</h3><ul><li>Rappeler les étapes prévues.</li><li>Recueillir les confirmations et retours du patient.</li><li>Reformuler les consignes déjà validées.</li><li>Signaler les demandes ambiguës ou hors programme.</li></ul></div>
<div class="panel reveal"><span class="tag">PROTÉGER</span><h3>Préserver la décision médicale</h3><ul><li>Aucun diagnostic autonome.</li><li>Aucune prescription ou modification de traitement.</li><li>Aucune interprétation clinique autonome.</li><li>Relais humain pour les situations sensibles ; urgence orientée vers les services compétents.</li></ul></div>
</div><div class="panel reveal" style="margin-top:13px"><div class="card-title">Problématique reformulée</div><p class="big-quote" style="font-size:clamp(14px,1.35vw,18px);margin:0">Comment aider les médecins à structurer le suivi de leurs patients à domicile, tout en rendant les consignes et les échéances plus accessibles aux patients, sans transférer la décision clinique à la plateforme ?</p></div>`},
{section:"ÉTUDE DU MARCHÉ",title:"Le suivi après la sortie : un besoin documenté, des réponses encore ciblées",kicker:"02 · MARCHÉ",content:"<div class=\"slide-body cols-2\">\n<div class=\"panel reveal\"><span class=\"tag\">UN ENJEU DE CONTINUITÉ DES SOINS</span><h3>La sortie de l'hôpital ne clôt pas le parcours</h3><p>Après une hospitalisation, le patient doit comprendre les consignes, surveiller son état, organiser ses examens et savoir qui contacter en cas de difficulté. Une sortie insuffisamment préparée peut fragiliser cette continuité.</p><div class=\"divider\"></div><h3>Des initiatives technologiques existent</h3><ul><li><b>Glyco-Wise :</b> projet universitaire cité dans le dossier initial, associant objets connectés et apprentissage automatique au suivi de la glycémie (A. Belgaïd, Université Abderrahmane Mira).</li><li><b>Health Guard :</b> projet universitaire cité dans le dossier initial autour d'un bracelet intelligent et de biocapteurs (Université Abou Bekr Belkaïd de Tlemcen).</li></ul><p class=\"note\">Ces exemples illustrent des approches ciblées. Ils ne suffisent pas à démontrer l'absence de toute solution globale sur le marché ; les références universitaires détaillées restent à compléter.</p></div>\n<div class=\"panel reveal\"><span class=\"tag\">DONNÉES SCIENTIFIQUES · 2022</span><h3>Un résultat favorable, dans un contexte précis</h3><div class=\"stat-grid\"><div class=\"stat\"><strong>1 885</strong><span>patients inclus dans l'étude</span></div><div class=\"stat\"><strong>−41%</strong><span>odds ajustés du recours combiné aux urgences ou à une réhospitalisation à 30 jours</span></div><div class=\"stat\"><strong>−55%</strong><span>odds ajustés de réhospitalisation à 30 jours</span></div></div><p>Étude de cohorte comparant des pratiques avant/après l'introduction de SMS automatisés, avec remontée des besoins à l'équipe. La baisse des visites aux urgences prises isolément n'était pas statistiquement significative.</p><p class=\"note\">Bressman et al., <i>JAMA Network Open</i>, 3 octobre 2022. <a href=\"https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2797716\" target=\"_blank\" rel=\"noopener\">Étude originale ↗</a></p></div>\n</div>\n<div class=\"callout footnote\"><b>Contrepoint scientifique · essai randomisé 2024 :</b> chez 4 736 patients, les revisites à 30 jours étaient de 23,9 % dans le groupe SMS et de 23,4 % dans le groupe témoin ; la différence n’était pas statistiquement significative. Les SMS automatisés seuls ne garantissent donc pas une baisse des recours aux soins aigus. <a href=\"https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2816890\" target=\"_blank\" rel=\"noopener\">Essai randomisé original ↗</a></div>\n<div class=\"callout footnote\"><b>Contexte algérien :</b> l'APS a rapporté le 11 avril 2026 que le ministère de la Santé avait achevé la préparation d'une plateforme de suivi à distance des dossiers médicaux et d'échange d'informations entre structures. Cela confirme une dynamique de numérisation ; MedLink DZ doit démontrer sa complémentarité sur l'organisation du suivi quotidien à domicile. <a href=\"https://www.aps.dz/fr/algerie/sante-et-environnement/mnun8thn-achevement-de-la-mise-en-place-d-une-plateforme-numerique-de-suivi-a-distance-des-dossiers-medicaux-des-patients\" target=\"_blank\" rel=\"noopener\">Source APS ↗</a></div>"},
{section:"ÉTUDE DU MARCHÉ",title:"Une enquête exploratoire menée auprès de professionnels de santé",kicker:"02 · MARCHÉ",content:"<div class=\"slide-body cols-2\">\n<div class=\"panel reveal\"><span class=\"tag\">QUESTIONNAIRE · 7 QUESTIONS</span><h3>Les questions posées</h3><ol><li>Quelle part de vos patients revient pour un suivi après une sortie d'hôpital ou une consultation ?</li><li>Avez-vous déjà constaté une aggravation faute de suivi après la sortie ?</li><li>Comment suivez-vous aujourd'hui vos patients à distance ?</li><li>Utilisez-vous déjà une application de rendez-vous (DZDOC, Docteur 360, etc.) ?</li><li>Que pensez-vous d'un assistant IA limité aux rappels, explications et signalement de nouveaux symptômes ?</li><li>Quelle est votre principale crainte concernant le projet ?</li><li>Quel point le projet doit-il absolument éviter ?</li></ol></div>\n<div class=\"panel reveal\"><span class=\"tag\">PRÉCAUTIONS D'INTERPRÉTATION</span><h3>Ce que les données permettent — et ne permettent pas — de dire</h3><div class=\"stat-grid\"><div class=\"stat\"><strong>7</strong><span>questions dans le questionnaire</span></div><div class=\"stat\"><strong>6</strong><span>questions avec répartitions chiffrées transmises</span></div><div class=\"stat\"><strong>1</strong><span>question à réponses qualitatives, sans pourcentages</span></div></div><p>Les pourcentages présentés ensuite sont ceux figurant dans les résultats communiqués par l'équipe. L'effectif exact, la date de collecte, le recrutement et les réponses brutes n'ont pas été fournis.</p><p class=\"gold\"><b>Limite :</b> impossible de vérifier les dénominateurs ou la représentativité. Ces résultats décrivent uniquement l'échantillon interrogé ; ils ne doivent pas être extrapolés à tous les professionnels de santé algériens.</p></div></div>\n<div class=\"callout footnote\">La collecte doit être documentée avant toute publication comme étude représentative : conserver le questionnaire, le nombre de répondants, la période, les profils et les réponses anonymisées.</div>"},
{section:"ÉTUDE DU MARCHÉ",title:"Résultats de l'enquête : suivi après sortie et aggravation perçue",kicker:"02 · MARCHÉ",content:"<div class=\"slide-body cols-2\">\n<div class=\"panel reveal\"><div class=\"card-title\">Part des patients revenant pour un suivi</div><div class=\"bar-list\"><div class=\"bar-row\"><span>Peu</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"45\"></div></div><b class=\"bar-value\">45%</b></div><div class=\"bar-row\"><span>La moitié</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"35\"></div></div><b class=\"bar-value\">35%</b></div><div class=\"bar-row\"><span>Presque tous</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"15\"></div></div><b class=\"bar-value\">15%</b></div><div class=\"bar-row\"><span>Presque aucun</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"5\"></div></div><b class=\"bar-value\">5%</b></div></div><p class=\"note\">Commentaires associés dans les réponses : difficultés de retour évoquées pour certains patients ruraux ou à faibles revenus ; suivi plus fréquent mentionné pour certaines pathologies lourdes ou chirurgies. Ces commentaires ne sont pas des statistiques par secteur ou pathologie.</p></div>\n<div class=\"panel reveal\"><div class=\"card-title\">Aggravation faute de suivi, selon les répondants</div><div class=\"stat-grid\"><div class=\"stat\"><strong>50%</strong><span>Souvent</span></div><div class=\"stat\"><strong>45%</strong><span>Parfois</span></div><div class=\"stat\"><strong>5%</strong><span>Jamais</span></div></div><p style=\"margin-top:16px\">Les répondants citent notamment le diabète, l'insuffisance cardiaque et les infections de cicatrice comme situations rencontrées.</p><p class=\"note\">Il s'agit de perceptions déclarées par les professionnels interrogés : elles ne démontrent pas, à elles seules, un lien causal entre absence de suivi et aggravation.</p></div></div>\n<p class=\"note footnote\">Source : résultats du questionnaire transmis par l'équipe. Effectif et données brutes non communiqués ; pourcentages à interpréter uniquement dans l'échantillon interrogé.</p>"},
{section:"ÉTUDE DU MARCHÉ",title:"Des pratiques à distance encore largement fondées sur le contact direct",kicker:"02 · MARCHÉ",content:"<div class=\"slide-body cols-2\">\n<div class=\"panel reveal\"><div class=\"card-title\">Canaux de suivi à distance déclarés</div><div class=\"bar-list\"><div class=\"bar-row\"><span>Téléphone</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"55\"></div></div><b class=\"bar-value\">55%</b></div><div class=\"bar-row\"><span>WhatsApp</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"25\"></div></div><b class=\"bar-value\">25%</b></div><div class=\"bar-row\"><span>Aucun moyen</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"15\"></div></div><b class=\"bar-value\">15%</b></div><div class=\"bar-row\"><span>SMS</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"5\"></div></div><b class=\"bar-value\">5%</b></div></div><p class=\"note\">Les réponses décrivent notamment des appels sur le numéro personnel du médecin et l'envoi, via WhatsApp, de photos de cicatrices, de bilans ou d'ordonnances.</p></div>\n<div class=\"panel reveal\"><div class=\"card-title\">Usage déclaré d'applications de rendez-vous</div><div class=\"metric\">100%</div><p class=\"metric-label\">Des répondants déclarent ne pas utiliser d'application de rendez-vous.</p><div class=\"divider\"></div><p>Cette réponse peut refléter les caractéristiques du groupe interrogé ou son niveau d'exposition aux outils numériques.</p><p class=\"note\">Elle ne signifie pas qu'aucune application n'existe en Algérie, ni qu'aucun professionnel ne les utilise. Le résultat doit être confronté à un échantillon plus large et diversifié.</p></div></div>\n<p class=\"note footnote\">Source : résultats du questionnaire transmis par l'équipe. Effectif et méthode d'échantillonnage non communiqués.</p>"},
{section:"ÉTUDE DU MARCHÉ",title:"Acceptabilité de l'IA : prudence, responsabilité et simplicité",kicker:"02 · MARCHÉ",content:"<div class=\"slide-body cols-2\">\n<div class=\"panel reveal\"><div class=\"card-title\">Perception d'un assistant IA limité aux rappels et alertes</div><div class=\"bar-list\"><div class=\"bar-row\"><span>Très favorable</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"25\"></div></div><b class=\"bar-value\">25%</b></div><div class=\"bar-row\"><span>Sceptique / peur des erreurs</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"65\"></div></div><b class=\"bar-value\">65%</b></div><div class=\"bar-row\"><span>Opposé</span><div class=\"bar-track\"><div class=\"bar-fill\" data-width=\"10\"></div></div><b class=\"bar-value\">10%</b></div></div><p class=\"note\">Les réserves exprimées portent notamment sur le risque de mauvais conseil ou de non-détection d'une urgence. Les répondants favorables insistent sur un rôle strictement limité aux rendez-vous et alertes.</p><div class=\"divider\"></div><div class=\"card-title\">Principale crainte déclarée</div><div class=\"stat-grid\"><div class=\"stat\"><strong>65%</strong><span>Responsabilité juridique</span></div><div class=\"stat\"><strong>35%</strong><span>Temps / surcharge de travail</span></div></div></div>\n<div class=\"panel reveal\"><div class=\"card-title\">Question 7 — points à éviter</div><div class=\"steps\" style=\"grid-template-columns:1fr\"><div class=\"step\"><div class=\"step-num\">01</div><h3>Harcèlement de notifications</h3><p>Préserver les temps de repos du médecin et lui laisser le contrôle des notifications.</p></div><div class=\"step\"><div class=\"step-num\">02</div><h3>Complexité d'utilisation</h3><p>Garder une interface intuitive, avec un minimum d'étapes et de saisies.</p></div><div class=\"step\"><div class=\"step-num\">03</div><h3>Exclusion des patients non connectés</h3><p>Prévoir des alternatives au tout-numérique et tenir compte des langues réellement parlées par les patients, notamment l'arabe et le kabyle.</p></div></div><p class=\"note\">Ces trois éléments sont des retours qualitatifs. Aucun pourcentage ni classement chiffré n'a été communiqué pour la question 7.</p></div></div>\n<div class=\"callout footnote\"><b>Conséquence pour MedLink DZ :</b> IA strictement encadrée et supervisée, notifications paramétrables, interface simple, et parcours alternatifs par SMS ou relais humain. Aucun diagnostic ni conseil médical autonome.</div>"},
{section:"CONCURRENCE",title:"Des acteurs établis couvrent déjà plusieurs briques du parcours",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">PLATEFORMES E-SANTÉ</span><h3>eTabib</h3><ul><li>Annuaire et visibilité des professionnels.</li><li>Rendez-vous et agenda en ligne.</li><li>Téléconsultation et partage de documents.</li><li>Care Team et fonctions annoncées de suivi du malade chronique.</li><li>Notifications SMS / e-mail selon les offres.</li></ul><p class="note"><a href="https://etabib.dz/fr/medecin-rdv-et-avis-medical-en-ligne/pro/" target="_blank" rel="noopener">Offre officielle ↗</a> · <a href="https://etabib-support.tawk.help/article/cest-quoi-etabib" target="_blank" rel="noopener">Détail des services ↗</a></p></div>
<div class="panel reveal"><span class="tag">PLATEFORMES E-SANTÉ</span><h3>ShifaConnect</h3><ul><li>Recherche par spécialité, localisation, disponibilité et avis.</li><li>Réservation en ligne et consultation vidéo.</li><li>Dossiers, ordonnances et profils patients.</li><li>Plans de traitement, gestion des patients et rappels annoncés.</li></ul><p class="note"><a href="https://shifaconnect.com/" target="_blank" rel="noopener">Site officiel ↗</a></p></div>
<div class="panel reveal"><span class="tag">ACCÈS ET GESTION</span><h3>Yadoct et outils de cabinet</h3><ul><li>Yadoct : rendez-vous, gestion de file d'attente et outils pour cliniques.</li><li>eTabib Workspace : logiciel de gestion de cabinet de l'écosystème eTabib.</li><li>Symtop et agendat.dz : solutions à documenter plus précisément avant comparaison détaillée.</li><li>Téléphone, WhatsApp et bouche-à-oreille restent des alternatives informelles.</li></ul><p class="note"><a href="https://yadoct.com/fr/about" target="_blank" rel="noopener">Yadoct ↗</a></p></div>
</div><div class="callout footnote"><b>Précaution :</b> repérage documentaire à partir des fonctionnalités publiquement annoncées. Il ne mesure ni la qualité réelle, ni l'adoption, ni l'étendue des fonctions accessibles selon les abonnements. Vérification directe à compléter.</div>`},
{section:"CONCURRENCE",title:"Le suivi est déjà présent chez certains concurrents",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">FONCTIONS DÉJÀ ANNONCÉES</span><div class="steps" style="grid-template-columns:1fr"><div class="step"><div class="step-num">ACCÈS</div><h3>Recherche et rendez-vous</h3><p>eTabib, ShifaConnect et Yadoct communiquent sur l'annuaire, la recherche de professionnels ou la réservation.</p></div><div class="step"><div class="step-num">GESTION</div><h3>Dossiers et organisation du cabinet</h3><p>eTabib et ShifaConnect annoncent des fonctions de gestion patient, de partage documentaire ou de plans de traitement.</p></div><div class="step"><div class="step-num">SUIVI</div><h3>Rappels et coordination</h3><p>eTabib présente Care Team et le suivi de patients chroniques ; des rappels sont également annoncés par plusieurs plateformes.</p></div></div></div>
<div class="panel reveal"><span class="tag">CONSÉQUENCE STRATÉGIQUE</span><h3>Ne pas revendiquer un marché vide</h3><p>MedLink DZ ne peut pas affirmer que ses concurrents ne proposent aucun suivi après consultation. Certaines briques sont déjà présentes dans des offres existantes.</p><div class="divider"></div><h3>La question à démontrer</h3><p>Existe-t-il un besoin non suffisamment couvert pour un programme de suivi post-consultation, avec tâches et échéances configurables, retours patients, relances déléguées et escalade vers le médecin ?</p><p class="note">Cette hypothèse doit être testée par des démonstrations comparatives et des entretiens avec des médecins.</p></div>
</div><div class="callout footnote">Les offres citées évoluent. La comparaison porte sur les fonctions publiquement annoncées, pas sur une inspection complète de chaque produit.</div>`},
{section:"CONCURRENCE",title:"Une différenciation à construire autour du workflow de suivi",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">01 · WORKFLOW STRUCTURÉ</span><h3>Un programme exploitable au quotidien</h3><ul><li>Consignes validées par le médecin.</li><li>Tâches, fréquences et échéances explicites.</li><li>Confirmation et retours du patient.</li><li>Historique des étapes et des échanges.</li></ul><p><b class="accent">Valeur recherchée :</b> rendre le suivi concret et traçable.</p></div>
<div class="panel reveal"><span class="tag">02 · ASSISTANCE PROGRESSIVE</span><h3>Du manuel à la délégation</h3><ul><li>Mode manuel piloté par le médecin.</li><li>Préparation assistée par IA, puis validation.</li><li>Check-ins et relances opérationnels selon les règles.</li><li>Escalade des demandes à examiner.</li></ul><p><b class="accent">Valeur recherchée :</b> réduire les tâches répétitives sans déléguer la décision clinique.</p></div>
<div class="panel reveal"><span class="tag">03 · GOUVERNANCE</span><h3>Contrôle médical et traçabilité</h3><ul><li>Validation avant publication.</li><li>Droits d'accès différenciés.</li><li>Historique des versions et actions.</li><li>Intervention humaine en cas de doute.</li></ul><p><b class="accent">Valeur recherchée :</b> instaurer un cadre de confiance.</p></div>
</div><div class="callout footnote">Ces éléments constituent une hypothèse de différenciation, pas une exclusivité démontrée. Ils devront être comparés aux fonctions réellement disponibles chez les concurrents.</div>`},
{section:"CONCURRENCE",title:"La valeur attendue pour chaque utilisateur",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">POUR LE PATIENT</span><h3>Comprendre ce qu'il doit faire ensuite</h3><ul><li>Retrouver les consignes publiées par son médecin.</li><li>Visualiser les prochaines étapes et échéances.</li><li>Confirmer une tâche ou transmettre un retour.</li><li>Savoir comment demander une aide ou reprendre contact.</li></ul><p class="note">Prévoir une expérience adaptée aux personnes peu connectées ou peu à l'aise avec le numérique.</p></div><div class="panel reveal"><span class="tag">POUR LE MÉDECIN</span><h3>Superviser sans perdre la maîtrise</h3><ul><li>Créer ou valider un programme de suivi.</li><li>Repérer les étapes non confirmées.</li><li>Consulter les retours et demandes à traiter.</li><li>Configurer les rappels et les règles d'escalade.</li></ul><p class="note">Le gain de temps et l'amélioration de la coordination restent à mesurer en pilote.</p></div></div><div class="callout"><b>Positionnement :</b> « MedLink DZ cherche à structurer le suivi entre les consultations, en complément des outils d'accès aux soins et de gestion de cabinet. »</div>`},
{section:"CONCURRENCE",title:"Positionnement retenu et preuves encore nécessaires",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">CE QUE L'ANALYSE MONTRE</span><ul><li>Le marché algérien comporte déjà des plateformes d'accès aux professionnels et des logiciels de cabinet.</li><li>Des concurrents annoncent aussi des fonctions de suivi, de coordination et de rappels.</li><li>La présence d'une fonction sur un site ne prouve pas son usage ni sa qualité réelle.</li><li>La confiance, la simplicité et la protection des données sont des conditions d'adoption.</li></ul></div><div class="panel reveal"><span class="tag">CE QUE MEDLINK DZ DOIT PROUVER</span><ul><li>Que les médecins ont un problème concret de suivi non suffisamment couvert.</li><li>Que le programme configurable améliore réellement l'organisation.</li><li>Que les patients comprennent et utilisent les rappels et retours.</li><li>Que la délégation opérationnelle réduit une charge sans créer de risque supplémentaire.</li></ul></div></div><div class="callout footnote">Le positionnement n'est pas « aucun concurrent ne fait cela », mais « nous voulons proposer un workflow de suivi plus adapté à un besoin précis, et nous devons le démontrer sur le terrain ».</div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Le cœur du produit : organiser le suivi après la consultation",kicker:"04 · SOLUTION",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">PARCOURS CENTRAL</span><p class="big-quote" style="margin:12px 0 16px">Le suivi médical ne s'arrête pas à la porte du cabinet.</p><p>Le médecin crée un programme, fixe les consignes et les échéances, puis valide sa publication. Le patient retrouve les étapes à suivre et transmet ses retours.</p><div class="divider"></div><div class="steps"><div class="step"><div class="step-num">01</div><h3>Définir</h3><p>Le médecin établit le programme.</p></div><div class="step"><div class="step-num">02</div><h3>Valider</h3><p>Il contrôle et publie la version retenue.</p></div><div class="step"><div class="step-num">03</div><h3>Suivre</h3><p>Le patient reçoit les rappels et transmet ses retours.</p></div></div></div><div class="panel reveal"><span class="tag">FONCTIONS COMPLÉMENTAIRES À SÉQUENCER</span><h3>Accès et services de proximité</h3><ul><li>Annuaire et recherche de médecins ou de cliniques.</li><li>Demande de rendez-vous et orientation vers le bon interlocuteur.</li><li>Demande de visite à domicile selon les disponibilités.</li><li>Suivi administratif des remboursements, uniquement après validation des partenaires et du cadre applicable.</li></ul><div class="divider"></div><p class="note">Ces modules élargissent le périmètre. Ils ne doivent pas retarder la validation du cœur de valeur : le programme de suivi et les retours patient-médecin.</p></div></div><div class="callout footnote">MedLink DZ facilite l'organisation du suivi ; il ne remplace ni la consultation ni le jugement du professionnel de santé.</div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Des espaces distincts, des responsabilités encadrées",kicker:"04 · SOLUTION",content:`
<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">TROIS ACTEURS PRINCIPAUX, ACCÈS DÉLÉGUÉ EN OPTION</span><div class="steps"><div class="step"><div class="step-num">PATIENT</div><h3>Consulter et participer</h3><p>Accéder au programme publié, consulter les consignes, recevoir les rappels et transmettre ses réponses ou demandes.</p></div><div class="step"><div class="step-num">MÉDECIN</div><h3>Créer, valider et suivre</h3><p>Gérer ses patients, préparer les programmes, contrôler leur contenu et examiner les retours ou alertes.</p></div><div class="step"><div class="step-num">ADMINISTRATION</div><h3>Vérifier et superviser</h3><p>Contrôler les justificatifs professionnels, gérer les comptes et traiter les incidents de la plateforme.</p></div></div><div class="divider"></div><p><b class="accent">Proche aidant :</b> accès éventuel aux informations du patient uniquement avec son autorisation et selon les droits accordés.</p></div><div class="panel reveal"><div class="image-slot" data-image="assets/images/espacepro.PNG"><div class="placeholder"><span class="placeholder-icon">▥</span><b>VÉRIFICATION DU PROFIL PROFESSIONNEL</b><span>Dépôt et examen des justificatifs</span></div><img alt="Formulaire de dépôt des justificatifs professionnels" loading="lazy"></div><div class="divider"></div><h3>Une validation avant l'accès professionnel</h3><p>Le compte médecin doit être contrôlé à partir des justificatifs demandés avant l'activation des fonctions réservées aux professionnels.</p><p class="footnote">La vérification par la plateforme ne remplace pas les agréments ou autorisations exigés par les autorités compétentes.</p></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Trois niveaux de suivi, un contrôle médical constant",kicker:"04 · SOLUTION",content:`
<div class="panel reveal"><span class="tag">UNE OFFRE PROGRESSIVE</span><p>Le médecin choisit le niveau d'assistance adapté à son organisation. L'automatisation augmente, mais la décision médicale reste humaine.</p></div><div class="slide-body cols-3" style="margin-top:13px"><div class="panel reveal"><span class="tag">ESSENTIEL · MANUEL</span><h3>Le médecin pilote tout</h3><ul><li>Création manuelle du programme</li><li>Consignes, tâches et échéances saisies par le médecin</li><li>Rappels automatiques selon le calendrier défini</li><li>Consultation des retours du patient</li></ul><div class="divider"></div><p><b>Automatisation :</b> rappels et organisation.</p></div><div class="panel reveal"><span class="tag">ASSISTÉ · IA</span><h3>L'IA prépare, le médecin valide</h3><ul><li>Le médecin formule ses instructions</li><li>L'IA propose une structure et un calendrier</li><li>Le médecin modifie et valide le programme</li><li>La version validée est publiée au patient</li></ul><div class="divider"></div><p><b>Automatisation :</b> aide à la préparation, sous validation.</p></div><div class="panel reveal"><span class="tag">DÉLÉGUÉ · IA PREMIUM</span><h3>L'assistant accompagne</h3><ul><li>Suivi et check-ins planifiés</li><li>Collecte des réponses du patient</li><li>Rappels et synthèses pour le médecin</li><li>Demandes hors programme signalées et transmises si nécessaire</li></ul><div class="divider"></div><p><b>Automatisation :</b> suivi opérationnel encadré.</p></div></div><div class="callout footnote">L'IA ne pose pas de diagnostic, ne prescrit pas et ne modifie jamais seule un traitement. Toute proposition de programme doit être validée par le médecin avant publication.</div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Un parcours de suivi, avec des relais clairement définis",kicker:"04 · SOLUTION",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">PARCOURS PATIENT</span><div class="steps"><div class="step"><div class="step-num">01 · PUBLICATION</div><h3>Le programme devient accessible</h3><p>Le patient retrouve les consignes et échéances validées par son médecin.</p></div><div class="step"><div class="step-num">02 · RAPPELS</div><h3>Les étapes sont rappelées</h3><p>Notifications dans l'application et, selon les services activés, par SMS ou e-mail.</p></div><div class="step"><div class="step-num">03 · RETOUR</div><h3>Le patient répond</h3><p>Il confirme une tâche, transmet une observation prévue ou formule une demande.</p></div><div class="step"><div class="step-num">04 · ESCALADE</div><h3>Le médecin est sollicité</h3><p>Les retours hors cadre ou nécessitant une appréciation humaine lui sont transmis.</p></div></div></div><div class="panel reveal"><div class="image-slot" data-image="assets/images/fonctionnalités.PNG"><div class="placeholder"><span class="placeholder-icon">⚙</span><b>NOTIFICATIONS ET DEMANDES</b><span>Exemple d'interface fonctionnelle</span></div><img alt="Paramètres des notifications et demandes dans MedLink DZ" loading="lazy"></div><div class="divider"></div><h3>Relais et modules complémentaires</h3><ul><li>SMS ou contact téléphonique lorsque l'accès Internet est indisponible, selon les services configurés.</li><li>Demande de rendez-vous ou de visite à domicile selon les professionnels disponibles.</li><li>Suivi administratif d'un dossier de remboursement : fonctionnalité complémentaire à valider avec les partenaires concernés, non assimilable à un remboursement effectué par MedLink DZ.</li><li>Une urgence ne doit jamais attendre la réponse de l'assistant : l'utilisateur doit contacter les services d'urgence compétents.</li></ul></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Architecture cible : services séparés et sécurité intégrée",kicker:"04 · SOLUTION",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Socle technique cible</div><div class="pill-list"><span>Next.js</span><span>TypeScript</span><span>API serveur</span><span>Supabase Auth</span><span>PostgreSQL</span><span>Row Level Security</span><span>Stockage sécurisé</span><span>Journal d'audit</span><span>Tâches planifiées</span><span>Service IA externe</span><span>Passerelle SMS</span></div><div class="divider"></div><h3>Flux de fonctionnement</h3><div class="steps"><div class="step"><div class="step-num">A</div><h3>Interface</h3><p>Espaces patient, médecin et administration.</p></div><div class="step"><div class="step-num">B</div><h3>Services métier</h3><p>Authentification, droits, programmes, historique et notifications.</p></div><div class="step"><div class="step-num">C</div><h3>Services externes</h3><p>IA et SMS via des fournisseurs à sélectionner et contractualiser.</p></div></div></div><div class="panel reveal"><div class="image-slot" data-image="assets/images/IMG1.jpg"><div class="placeholder"><span class="placeholder-icon">▧</span><b>VUE CONCEPTUELLE DU SERVICE</b><span>Illustration du suivi hybride</span></div><img alt="Illustration conceptuelle du suivi médical hybride" loading="lazy"></div><div class="divider"></div><h3>Garde-fous à concevoir et tester</h3><ul><li>Accès aux données selon le rôle et le besoin légitime.</li><li>Traçabilité des consultations et modifications.</li><li>Validation humaine des contenus médicaux avant publication.</li><li>Escalade des demandes sensibles vers un professionnel.</li><li>Cartographie de l'hébergement, des sous-traitants et des transferts.</li><li>Tests de sécurité, sauvegardes et procédure de gestion des incidents.</li></ul></div></div><div class="callout footnote">Architecture cible, non preuve de conformité ou de mise en production. Le choix des fournisseurs et les traitements de données de santé doivent être validés avant ouverture publique.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Un modèle B2B par abonnement professionnel",kicker:"05 · BUSINESS MODEL",content:`
<div class="slide-body cols-3 plan-grid">
<div class="panel reveal plan-card">
<span class="tag">ESSENTIEL · SUIVI MANUEL</span><div class="metric">2 500 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>Le médecin organise et pilote chaque étape.</h3>
<div class="plan-section"><b>Gestion du cabinet et des patients</b><ul><li>Espace professionnel avec liste et fiches patients</li><li>Centralisation des informations utiles au suivi</li><li>Gestion des rendez-vous et demandes de visites à domicile</li></ul></div>
<div class="plan-section"><b>Programme de suivi manuel</b><ul><li>Création des consignes, tâches et étapes par le médecin</li><li>Définition des dates, fréquences et échéances quotidiennes ou hebdomadaires</li><li>Modification et publication après validation explicite</li><li>Suivi manuel de l'avancement des tâches</li></ul></div>
<div class="plan-section"><b>Communication et rappels</b><ul><li>Messagerie et historique des échanges</li><li>Notifications dans l'application et rappels par SMS</li><li>Relance et reprise de contact à l'initiative du professionnel</li><li>SMS pour les patients sans connexion Internet, selon le quota du forfait</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les médecins qui veulent un outil structuré, tout en conservant la gestion directe du suivi.</p>
</div>
<div class="panel reveal plan-card plan-featured">
<span class="tag">ASSISTÉ · INTELLIGENCE ARTIFICIELLE</span><div class="metric">5 000 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>L'IA prépare et facilite. Le médecin décide.</h3>
<div class="plan-section"><b>Tout le contenu du plan Essentiel</b><ul><li>Gestion des patients, rendez-vous et visites à domicile</li><li>Programmes manuels possibles à tout moment</li><li>Notifications dans l'application et rappels par SMS</li></ul></div>
<div class="plan-section"><b>Préparation assistée par IA</b><ul><li>Génération d'une première ébauche de programme à partir des instructions écrites du médecin</li><li>Proposition de tâches, fréquences, dates et rappels</li><li>Révision et ajustement par le médecin avant publication</li></ul></div>
<div class="plan-section"><b>Assistant patient encadré</b><ul><li>Réponses aux questions simples à partir du programme et des contenus validés</li><li>Rappel et reformulation des consignes déjà publiées</li><li>Identification des demandes hors programme ou ambiguës</li><li>Transmission au médecin avec résumé et contexte</li><li>SMS disponibles pour les patients sans connexion Internet, selon quota</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les médecins qui veulent réduire la saisie répétitive et mieux traiter les demandes courantes, sans déléguer la décision médicale.</p>
</div>
<div class="panel reveal plan-card">
<span class="tag">DÉLÉGUÉ · IA PREMIUM</span><div class="metric">8 000 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>L'agent exécute le suivi opérationnel selon les règles du médecin.</h3>
<div class="plan-section"><b>Tout le contenu du plan Assisté</b><ul><li>Gestion du cabinet, patients, rendez-vous et visites à domicile</li><li>Programmes assistés ou entièrement manuels</li><li>Assistant patient et rappels SMS</li></ul></div>
<div class="plan-section"><b>Suivi délégué et relances</b><ul><li>Déclenchement de check-ins quotidiens ou hebdomadaires selon le programme validé</li><li>Relances automatiques en cas de tâche non confirmée ou de réponse manquante</li><li>Collecte structurée des retours du patient</li><li>Détection des réponses nécessitant une vérification humaine</li></ul></div>
<div class="plan-section"><b>Supervision et capacité renforcées</b><ul><li>Synthèse périodique de l'avancement et des échanges pour le médecin</li><li>Alertes et escalade des demandes sensibles ou hors périmètre</li><li>Historique des relances, réponses, alertes et interventions</li><li>Capacité prévue pour un volume supérieur de patients et d'interactions simultanées</li><li>SMS disponibles pour les patients sans connexion Internet, selon quota</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les professionnels qui souhaitent déléguer une partie du suivi organisationnel et des relances, tout en gardant le contrôle clinique.</p>
</div>
</div>
<div class="callout footnote">Offres et tarifs proposés, non encore commercialisés. Les quotas mensuels (patients actifs, SMS, interactions IA), conditions de dépassement et coûts variables restent à chiffrer avant lancement. Les modules de cabinet, d'annuaire, de rendez-vous et de visite à domicile décrivent la cible tarifaire complète : leur déploiement doit être progressif et ne conditionne pas la validation du cœur de suivi. Dans tous les plans, le médecin conserve la responsabilité de la validation médicale ; l'IA ne diagnostique pas, ne prescrit pas et ne modifie pas seule un programme.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"La valeur est liée au temps et à l'organisation",kicker:"05 · BUSINESS MODEL",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Pour le médecin</div><ul><li>Centraliser les programmes de suivi</li><li>Réduire la dispersion des consignes</li><li>Rendre les étapes visibles</li><li>Garder la main sur la validation et la publication</li></ul><div class="divider"></div><p class="note">Le gain de temps doit être mesuré lors d'un pilote, et non présenté comme un résultat déjà démontré.</p></div><div class="panel reveal"><div class="card-title">Pour le patient</div><ul><li>Retrouver les consignes au même endroit</li><li>Comprendre les étapes à venir</li><li>Recevoir des rappels utiles</li><li>Savoir comment reprendre contact</li></ul><div class="divider"></div><p class="note">L'accessibilité doit inclure les patients peu connectés ou peu à l'aise avec le numérique.</p></div></div><div class="callout footnote">Le payeur principal envisagé est le professionnel de santé ; l'accès patient est pensé comme une composante du service.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Des charges prévisionnelles, encore à confirmer",kicker:"05 · STRUCTURE DE COÛTS",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Prestataires et dépenses recensées</div><table class="data-table"><thead><tr><th>Poste</th><th>Prestataire</th><th>Coût estimé</th></tr></thead><tbody><tr><td>IA</td><td>DzTokens</td><td>10 000 DA / mois</td></tr><tr><td>Hébergement</td><td>ISSAL NET · FlexCompute</td><td>17 500 DA HT / mois</td></tr><tr><td>Domaine</td><td>HOSTARTS · DZ + COM</td><td>4 816 DA / an</td></tr><tr><td>Publicité</td><td>Meta Ads + Google Ads</td><td>50 000 DA / mois</td></tr><tr><td>Gestion marketing</td><td>AdsMedia</td><td>35 000 DA / mois</td></tr><tr><td>SMS</td><td>LINKSY · Flex Pro</td><td>12 000 DA / mois</td></tr><tr><td>Appels</td><td>LINKSY ou fournisseur compatible</td><td>Sur devis</td></tr></tbody></table><div class="divider"></div><div class="stat-grid"><div class="stat"><strong>124 500</strong><span>DA / mois · charges recensées</span></div><div class="stat"><strong>1 498 816</strong><span>DA / an, domaine inclus</span></div></div></div><div class="panel reveal"><span class="tag">LECTURE CRITIQUE DU BUDGET</span><h3>Les coûts ne sont pas encore complets</h3><p>La publicité et sa gestion représentent 85 000 DA par mois, soit environ 68 % des charges mensuelles recensées. Ce budget d'acquisition doit être justifié par un plan commercial et des objectifs mesurables.</p><div class="divider"></div><ul><li>Consommation réelle de tokens IA et de SMS à mesurer.</li><li>Capacité d'hébergement et sauvegardes à confirmer.</li><li>Frais de paiement, appels, support et maintenance à chiffrer.</li><li>Coûts juridiques, comptables, fiscaux et salariaux non intégrés.</li></ul><p class="note">Les appels sont exclus du total. Les montants doivent être confirmés par devis et conditions contractuelles.</p></div></div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"50 médecins : un chiffre d'affaires projeté de 230 000 DA",kicker:"05 · REVENUS",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Répartition des abonnements</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Formule</th><th>Médecins</th><th>Prix / mois</th><th>Revenu</th></tr></thead><tbody><tr><td>Essentiel · Manuel</td><td>20</td><td>2 500 DA</td><td><b>50 000 DA</b></td></tr><tr><td>Assisté · IA</td><td>20</td><td>5 000 DA</td><td><b>100 000 DA</b></td></tr><tr><td>Délégué · IA Premium</td><td>10</td><td>8 000 DA</td><td><b>80 000 DA</b></td></tr><tr><td colspan="3"><b>Total · 50 médecins</b></td><td><b class="accent">230 000 DA</b></td></tr></tbody></table></div></div><div class="panel reveal"><div class="card-title">Revenus prévisionnels</div><div class="stat-grid"><div class="stat"><strong>230 000</strong><span>DA / mois</span></div><div class="stat"><strong>2 760 000</strong><span>DA / an</span></div><div class="stat"><strong>4 600</strong><span>DA / médecin / mois · revenu moyen</span></div></div><div class="divider"></div><p>Le revenu moyen est calculé à partir du mix : 230 000 DA ÷ 50 abonnés.</p><p class="note">Scénario cible, pas un portefeuille de clients déjà acquis. Les revenus hors forfait ne sont pas inclus.</p></div></div><div class="callout footnote">Le SMS est prévu dans les trois formules pour les patients sans connexion Internet. Les quotas et dépassements doivent être définis contractuellement.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Un solde prévisionnel positif, sous hypothèses",kicker:"05 · RENTABILITÉ",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Compte d'exploitation simplifié</div><div class="stat-grid"><div class="stat"><strong>230 000 DA</strong><span>Revenus mensuels projetés</span></div><div class="stat"><strong>−124 500 DA</strong><span>Charges mensuelles recensées</span></div><div class="stat"><strong>105 500 DA</strong><span>Solde mensuel indicatif</span></div><div class="stat"><strong>1 261 184 DA</strong><span>Solde annuel indicatif, domaine inclus</span></div></div><p class="note">Le calcul annuel utilise 2 760 000 DA de revenus moins 1 498 816 DA de charges recensées. Il ne constitue pas un compte de résultat comptable complet.</p></div><div class="panel reveal"><span class="tag">INDICATEUR DE SCÉNARIO</span><div class="metric">84,15%</div><p class="metric-label">Excédent annuel rapporté aux charges recensées</p><div class="divider"></div><p>Ce ratio compare le solde calculé aux charges listées. Il ne doit pas être présenté comme le ROI d'un investissement initial : le capital investi et les coûts complets ne sont pas chiffrés.</p><p class="note">Projection avant impôts, rémunérations, appels, frais de paiement, coûts variables supplémentaires et dépenses non recensées. Le résultat dépend de l'acquisition effective de 50 médecins au mix tarifaire prévu.</p></div></div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Le seuil de couverture des charges recensées est estimé à 28 médecins",kicker:"05 · SEUIL DE RENTABILITÉ",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Revenus et charges selon le nombre d'abonnés</div><table class="data-table"><thead><tr><th>Médecins</th><th>Revenus mensuels</th><th>Charges recensées</th><th>Écart</th></tr></thead><tbody><tr><td>20</td><td>92 000 DA</td><td>124 500 DA</td><td>−32 500 DA</td></tr><tr><td>27</td><td>124 200 DA</td><td>124 500 DA</td><td>−300 DA</td></tr><tr><td><b>28</b></td><td><b>128 800 DA</b></td><td>124 500 DA</td><td><b>+4 300 DA</b></td></tr><tr><td>50</td><td>230 000 DA</td><td>124 500 DA</td><td>+105 500 DA</td></tr></tbody></table><p class="note">Modèle simplifié : revenu moyen constant de 4 600 DA par médecin et charges mensuelles recensées de 124 500 DA.</p></div><div class="panel reveal"><span class="tag">SEUIL INDICATIF</span><div class="metric">28</div><p class="metric-label">Médecins abonnés pour couvrir les charges recensées</p><div class="divider"></div><p><b>Calcul :</b> 124 500 ÷ 4 600 = 27,07, arrondi à 28 médecins.</p><ul><li>À 27 médecins : 124 200 DA de revenus, soit 300 DA sous les charges recensées.</li><li>À 28 médecins : 128 800 DA de revenus, soit 4 300 DA au-dessus.</li></ul><p class="note">Ce n'est pas un seuil de rentabilité complet : les coûts variables, les appels, les impôts, les salaires et les autres charges non recensées peuvent relever le seuil. Le mix réel des packs modifie également le revenu moyen.</p></div></div>`},{section:"ÉTUDE JURIDIQUE",title:"Choisir une structure adaptée",kicker:"06 · JURIDIQUE",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Piste étudiée : SARL</div><div class="metric">2–50</div><p class="metric-label">Nombre d'associés indiqué pour la SARL.</p><div class="divider"></div><p>Une équipe de six personnes entre dans cette fourchette. Le capital, la répartition des parts, la gérance et les formalités doivent être définis avec un notaire et le CNRC.</p><p class="note">Référence : article 590 du Code de commerce, modifié par la loi n° 15-20 du 30 décembre 2015.</p></div><div class="panel reveal"><div class="card-title">Démarches à cadrer</div><ul><li>Choisir la dénomination et l'objet social</li><li>Définir les associés et les apports</li><li>Rédiger les statuts</li><li>Effectuer les formalités d'immatriculation</li><li>Organiser la comptabilité et les obligations fiscales</li><li>Évaluer l'éligibilité au label startup</li></ul></div></div><div class="callout footnote">La SARL est une piste de structuration, pas une société déjà constituée ni un avis juridique définitif.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"Le label « Projet innovant » : la voie adaptée à MedLink DZ",kicker:"06 · LABELLISATION",content:`
<div class="slide-body cols-2">
  <div class="panel reveal">
    <span class="tag">1 · QUI PEUT CANDIDATER ?</span>
    <h3>Une équipe, même sans société constituée</h3>
    <ul>
      <li><b>Base légale :</b> décret exécutif n° 20-254 du 15 septembre 2020, articles 16 à 20, modifié notamment par le décret n° 21-422 du 4 novembre 2021.</li>
      <li><b>Éligibilité :</b> toute personne physique ou tout groupe de personnes physiques portant un projet lié à l’innovation.</li>
      <li><b>Pas de société préalable :</b> le label « Projet innovant » vise précisément les porteurs qui n’ont pas encore créé leur entreprise.</li>
      <li><b>Pour MedLink DZ :</b> la candidature peut être portée collectivement par les membres de l’équipe. Les six associés envisagés ne sont pas un obstacle au titre de ce dispositif.</li>
    </ul>
    <div class="divider"></div>
    <p class="note"><b>À ne pas confondre :</b> le label « Startup » concerne une société déjà constituée et obéit à des critères distincts (âge de la société, capital, chiffre d’affaires, effectif…).</p>
  </div>
  <div class="panel reveal">
    <span class="tag">2 · CE QUE LE COMITÉ DOIT POUVOIR ÉVALUER</span>
    <h3>Les quatre preuves centrales du dossier</h3>
    <ul>
      <li><b>Innovation :</b> présentation du projet et démonstration précise de ses aspects innovants.</li>
      <li><b>Potentiel économique :</b> éléments établissant un fort potentiel de croissance (marché, clients, modèle économique, capacité de déploiement).</li>
      <li><b>Équipe :</b> qualifications scientifiques et/ou techniques et expérience des personnes chargées du projet.</li>
      <li><b>Éléments complémentaires, s’ils existent :</b> propriété intellectuelle et prix ou récompenses obtenus.</li>
    </ul>
    <p class="note">Le texte ne fixe pas une grille de points publique ni une garantie d’acceptation : le comité national apprécie le dossier et son caractère innovant.</p>
  </div>
</div>
<div class="slide-body cols-2" style="margin-top:12px">
  <div class="panel reveal">
    <span class="tag">3 · PIÈCES ET CHAMPS DU PORTAIL OFFICIEL</span>
    <ul>
      <li>Identité et coordonnées du demandeur : NIN, nom, prénom, âge, téléphone, e-mail, wilaya et adresse.</li>
      <li>Profil du porteur et des cofondateurs : niveau de qualification, noms/niveaux des autres fondateurs et CV.</li>
      <li>Projet : nom, secteur, description courte (400 caractères maximum), présentation détaillée et aspects d’innovation.</li>
      <li><b>Pitch deck :</b> utiliser le modèle « Projet innovant » téléchargeable sur Startup.dz.</li>
      <li>Avancement, modèle économique (B2B, B2C, B2G ou autre) et adresse du site web, si disponible.</li>
      <li>Selon la situation : attestation d’incubation, inscription liée à la décision ministérielle n° 1275, justificatifs de propriété intellectuelle, concours et récompenses.</li>
    </ul>
  </div>
  <div class="panel reveal">
    <span class="tag">4 · PROCÉDURE ET DURÉE</span>
    <div class="steps">
      <div class="step"><div class="step-num">01 · DÉPÔT</div><h3>Candidature en ligne</h3><p>Soumettre le dossier via le portail national Startup.dz.</p></div>
      <div class="step"><div class="step-num">02 · EXAMEN</div><h3>Instruction par le comité</h3><p>Réponse prévue dans un délai maximal de 30 jours à compter du dépôt.</p></div>
      <div class="step"><div class="step-num">03 · COMPLÉMENT</div><h3>Répondre aux demandes</h3><p>En cas de pièces manquantes, le délai est suspendu ; les éléments demandés doivent être transmis sous 15 jours après notification, sous peine de rejet.</p></div>
      <div class="step"><div class="step-num">04 · DÉCISION</div><h3>Attribution ou refus motivé</h3><p>Les décisions d’attribution sont publiées sur le portail. Un refus peut faire l’objet d’une demande motivée de réexamen.</p></div>
    </div>
    <div class="divider"></div>
    <p><b>Validité :</b> 2 ans, renouvelable 2 fois selon les mêmes formes (durée théorique maximale de 6 ans).</p>
  </div>
</div>
<div class="callout footnote"><b>Application à MedLink DZ :</b> présenter une innovation démontrable dans le suivi post-consultation (programme validé par le médecin, coordination patient-médecin, rappels multicanaux et assistance IA strictement encadrée), documenter le besoin et le marché, montrer un prototype fonctionnel et expliquer comment le modèle peut être déployé à grande échelle. Le prototype, l’incubation, les titres de propriété intellectuelle et les récompenses sont des éléments complémentaires : ne pas les déclarer obligatoires lorsqu’ils ne le sont pas dans le décret. Sources : décret n° 20-254, art. 16–20 ; décret n° 21-422, art. 8 ; formulaire officiel Startup.dz.</div>
<div class="callout"><b>Portail de candidature :</b> <a href="https://startup.dz/label-projet/" target="_blank" rel="noopener noreferrer">startup.dz/label-projet</a> · <a href="https://www.joradp.dz/FTP/jo-francais/2021/F2021084.pdf" target="_blank" rel="noopener noreferrer">Journal officiel n° 84 du 4 novembre 2021</a> · <a href="https://www.joradp.dz/FTP/jo-francais/2025/F2025081.pdf" target="_blank" rel="noopener noreferrer">Mise à jour réglementaire du 7 décembre 2025</a></div>`},
{section:"ÉTUDE JURIDIQUE",title:"Données personnelles et santé : les textes structurants",kicker:"06 · JURIDIQUE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">LOI N° 18-07 · MODIFIÉE EN 2025</span><h3>Données personnelles et données de santé</h3><ul><li><b>Articles 3, 7 et 9 :</b> définitions, conditions de licéité et encadrement des données sensibles, à lire dans la version consolidée.</li><li><b>Articles 12 à 14 :</b> formalités et informations liées au traitement, selon la qualification applicable.</li><li><b>Articles 41 bis et 41 bis 1 :</b> désignation d'un délégué à la protection des données et définition de ses missions.</li><li><b>Articles 41 bis 2 et 41 bis 3 :</b> registre des traitements et carnet automatisé des opérations.</li></ul><div class="divider"></div><p class="note">La loi 25-11 du 24 juillet 2025 modifie et complète la loi 18-07. Les formalités doivent être examinées sur le texte consolidé et auprès de l'ANPDP.</p></div><div class="panel reveal"><span class="tag">LOI N° 18-11 · SANTÉ</span><h3>Droits du patient et secret professionnel</h3><ul><li><b>Articles 23 et 24 :</b> droits du patient, information, vie privée et confidentialité.</li><li><b>Article 169 :</b> secret professionnel dans le cadre des professions de santé.</li><li><b>Article 186 :</b> exercice illégal de la médecine, notamment lorsque des actes de diagnostic ou de traitement sont accomplis habituellement par une personne non habilitée.</li></ul><div class="divider"></div><p><b>Application à MedLink DZ :</b> les dossiers, programmes et échanges peuvent contenir des données de santé sensibles. Les rôles du médecin, de la plateforme et des sous-traitants doivent être qualifiés avant toute mise en production.</p></div></div>`},
{section:"ÉTUDE JURIDIQUE",title:"Les obligations à traduire en mesures opérationnelles",kicker:"06 · JURIDIQUE",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Traitement et gouvernance des données</div><ul><li><b>Avant collecte :</b> définir responsable, finalités, données, destinataires et durées de conservation.</li><li><b>Formalités ANPDP :</b> déterminer le régime préalable applicable au traitement concerné.</li><li><b>Information et droits :</b> préparer l'information du patient et les procédures d'exercice de ses droits.</li><li><b>Délégué :</b> prévoir la désignation du délégué à la protection des données conformément à l'article 41 bis et communiquer ses coordonnées à l'autorité nationale.</li><li><b>Registres :</b> le responsable du traitement et le sous-traitant tiennent chacun les registres et carnets prévus aux articles 41 bis 2 et 41 bis 3.</li></ul></div><div class="panel reveal"><div class="card-title">Sécurité et responsabilités</div><ul><li><b>Secret professionnel :</b> limiter les accès aux personnes habilitées et aux besoins du suivi.</li><li><b>Contrats :</b> définir les rôles, instructions, accès et engagements des sous-traitants.</li><li><b>Hébergement :</b> cartographier stockage, accès fournisseurs et transferts internationaux ; examiner l'article 44.</li><li><b>Incidents :</b> préparer détection, documentation et réponse selon les obligations effectivement applicables.</li><li><b>IA :</b> limiter les entrées transmises aux prestataires et vérifier les conditions de traitement des données par chaque fournisseur.</li></ul></div></div><div class="callout footnote"><b>Attention :</b> les articles 45 bis 6 à 10 de la loi 18-07 modifiée s'inscrivent dans le titre spécifique aux traitements à des fins de prévention et de détection des infractions, d'enquêtes et de poursuites pénales. Le délai de cinq jours de l'article 45 bis 8 ne doit pas être présenté comme une règle générale applicable automatiquement à MedLink DZ. Les formalités et transferts doivent être vérifiés sur le cas concret.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"L'assistant IA reste hors du champ de la décision clinique",kicker:"06 · JURIDIQUE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">PÉRIMÈTRE AUTORISÉ PAR LA CONCEPTION</span><h3>Assistance organisationnelle</h3><ul><li>Retrouver les informations d'un programme validé.</li><li>Reformuler des consignes déjà publiées, sans les modifier.</li><li>Rappeler les tâches et échéances prévues.</li><li>Recueillir les réponses attendues et préparer une synthèse.</li><li>Orienter vers le médecin lorsque la demande sort du cadre.</li></ul></div><div class="panel reveal"><span class="tag">FONCTIONS EXCLUES</span><h3>Aucune décision médicale autonome</h3><ul><li>Établir un diagnostic.</li><li>Prescrire ou modifier un traitement.</li><li>Décider de la conduite à tenir en urgence.</li><li>Modifier le programme médical sans validation.</li><li>Remplacer l'appréciation d'un professionnel habilité.</li></ul></div></div><div class="callout footnote"><b>Cadre :</b> l'article 186 de la loi 18-11 vise notamment l'établissement habituel d'un diagnostic ou l'administration d'un traitement par une personne non habilitée. Le produit doit donc maintenir l'assistant dans un rôle organisationnel et prévoir un relais humain ; cette diapositive ne constitue pas une qualification juridique définitive du système IA.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"Conditions de passage au lancement public",kicker:"06 · JURIDIQUE",content:`
<div class="panel reveal"><div class="steps"><div class="step"><div class="step-num">01 · JURIDIQUE</div><h3>Valider le cadre</h3><p>Structure, données de santé, contrats, formalités et obligations applicables.</p></div><div class="step"><div class="step-num">02 · SÉCURITÉ</div><h3>Auditer le produit</h3><p>Contrôle d'accès, tests, sauvegardes, incidents et protection des données.</p></div><div class="step"><div class="step-num">03 · TERRAIN</div><h3>Piloter avec prudence</h3><p>Tester avec des professionnels volontaires et des données adaptées.</p></div><div class="step"><div class="step-num">04 · PUBLIC</div><h3>Ouvrir progressivement</h3><p>Après validation, support, documentation et suivi des indicateurs.</p></div></div></div><div class="callout footnote">Aucune autorisation ministérielle, conformité complète ou labellisation startup n'est présentée comme déjà acquise.</div>`},
{section:"CONCLUSION",title:"Structurer le suivi. Renforcer le lien.",kicker:"MEDLINK DZ · CONCLUSION",kind:"closing",content:`
<div class="cover-visual"><div class="orb"><i class="orb-node n1"></i><i class="orb-node n2"></i><i class="orb-node n3"></i></div><div class="orb-core">M</div></div><span class="tag">UNE PLATEFORME DE COORDINATION</span><h1>MedLink <span class="accent">DZ</span></h1><p class="lead">Un suivi plus clair pour le patient. Un meilleur cadre de coordination pour le médecin. La décision médicale reste humaine.</p><a href="https://medlink-dz-three.vercel.app" target="_blank" rel="noopener noreferrer" style="display:inline-flex;align-items:center;gap:10px;margin:18px auto 8px;padding:13px 22px;border:1px solid var(--accent);border-radius:999px;color:var(--accent);font-weight:700;text-decoration:none;letter-spacing:.02em">Découvrir le produit MedLink DZ <span aria-hidden="true">↗</span></a><div class="cover-foot" style="justify-content:center"><span>Merci</span><span>Questions & échanges</span></div>`}
];

const stage=document.querySelector("#stage");
const progress=document.querySelector("#progress-fill");
const progressLabel=document.querySelector("#progress-label");
const sectionLabel=document.querySelector("#section-label");
const overview=document.querySelector("#overview");
const overviewGrid=document.querySelector("#overview-grid");
let current=0, locked=false;

function renderSlide(index,animate=true){
  current=Math.max(0,Math.min(slides.length-1,index));
  const s=slides[current];
  const old=stage.querySelector(".slide");
  if(old&&animate){old.classList.add("exit");setTimeout(()=>mount(),170)}else mount();
  function mount(){
    const slide=document.createElement("article");
    slide.className="slide"+(s.kind==="cover"?" slide-cover":"")+(s.kind==="closing"?" closing":"");
    const head=s.kind==="cover"||s.kind==="closing"?"":`<header class="slide-head reveal"><div><span class="eyebrow">${s.kicker}</span><h2>${s.title}</h2></div></header>`;
    slide.innerHTML=head+s.content;
    stage.replaceChildren(slide);
    requestAnimationFrame(()=>{slide.classList.add("active");animateBars(slide);loadImages(slide)});
    sectionLabel.textContent=s.section;
    progress.style.width=((current+1)/slides.length*100)+"%";
    progressLabel.textContent=String(current+1).padStart(2,"0")+" / "+String(slides.length).padStart(2,"0");
    document.title=(current+1)+". "+s.title+" — MedLink DZ";
    document.querySelector("#prev-btn").disabled=current===0;
    document.querySelector("#next-btn").disabled=current===slides.length-1;
    document.querySelectorAll(".overview-card").forEach((el,i)=>el.classList.toggle("active",i===current));
  }
}
function animateBars(root){root.querySelectorAll(".bar-fill").forEach(el=>{const w=el.dataset.width;requestAnimationFrame(()=>el.style.width=w+"%")})}
function loadImages(root){root.querySelectorAll(".image-slot").forEach(slot=>{const img=slot.querySelector("img");const src=slot.dataset.image;if(!img||!src)return;const reveal=()=>{if(img.naturalWidth&&img.naturalHeight){slot.style.setProperty("--image-ratio",img.naturalWidth+"/"+img.naturalHeight);slot.classList.add("is-loaded")}};img.addEventListener("load",reveal,{once:true});img.addEventListener("error",()=>slot.classList.remove("is-loaded"),{once:true});img.src=src;if(img.complete)reveal()})}
function go(delta){if(locked||overview.classList.contains("hidden")===false)return;const next=Math.max(0,Math.min(slides.length-1,current+delta));if(next===current)return;locked=true;renderSlide(next);setTimeout(()=>locked=false,260)}
function buildOverview(){overviewGrid.innerHTML=slides.map((s,i)=>`<button class="overview-card ${i===current?"active":""}" data-index="${i}"><span>${String(i+1).padStart(2,"0")} · ${s.section}</span><b>${s.title}</b></button>`).join("");overviewGrid.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{overview.classList.add("hidden");overview.setAttribute("aria-hidden","true");renderSlide(Number(b.dataset.index))}))}
function toggleOverview(force){const open=typeof force==="boolean"?force:overview.classList.contains("hidden");overview.classList.toggle("hidden",!open);overview.setAttribute("aria-hidden",String(!open))}
document.querySelector("#prev-btn").addEventListener("click",()=>go(-1));
document.querySelector("#next-btn").addEventListener("click",()=>go(1));
document.querySelector("#overview-btn").addEventListener("click",()=>toggleOverview());
document.querySelector("#close-overview").addEventListener("click",()=>toggleOverview(false));
document.querySelector("#fullscreen-btn").addEventListener("click",()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.());
document.addEventListener("keydown",e=>{
 if(e.key==="Escape"){toggleOverview(false);document.querySelector("#help").classList.add("hidden");return}
 if(!overview.classList.contains("hidden"))return;
 if(["ArrowRight"," ","PageDown"].includes(e.key)){e.preventDefault();go(1)}
 if(["ArrowLeft","PageUp"].includes(e.key)){e.preventDefault();go(-1)}
 if(e.key==="Home"){renderSlide(0)}
 if(e.key==="End"){renderSlide(slides.length-1)}
 if(e.key.toLowerCase()==="f"){document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.()}
 if(e.key.toLowerCase()==="g"){toggleOverview()}
 if(e.key==="?"||e.key==="/")document.querySelector("#help").classList.toggle("hidden");
});
document.querySelector("#close-help").addEventListener("click",()=>document.querySelector("#help").classList.add("hidden"));
let touchX=0;
stage.addEventListener("touchstart",e=>touchX=e.changedTouches[0].screenX,{passive:true});
stage.addEventListener("touchend",e=>{const dx=e.changedTouches[0].screenX-touchX;if(Math.abs(dx)>70)go(dx<0?1:-1)},{passive:true});
buildOverview();renderSlide(0,false);

// Lightweight ambient particle field (2D canvas).
const canvas=document.querySelector("#particle-field"),ctx=canvas.getContext("2d");
let particles=[],cw=0,ch=0,raf;
function resizeCanvas(){const dpr=Math.min(devicePixelRatio||1,2);cw=canvas.clientWidth;ch=canvas.clientHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:Math.min(75,Math.floor(cw*ch/18000))},()=>({x:Math.random()*cw,y:Math.random()*ch,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18,r:Math.random()*1.4+.4}))}
function drawParticles(){ctx.clearRect(0,0,cw,ch);for(let i=0;i<particles.length;i++){const p=particles[i];p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>cw)p.vx*=-1;if(p.y<0||p.y>ch)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle="rgba(125,226,211,.42)";ctx.fill();for(let j=i+1;j<particles.length;j++){const q=particles[j],dx=p.x-q.x,dy=p.y-q.y,d=Math.hypot(dx,dy);if(d<105){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle="rgba(91,185,183,"+(1-d/105)*.12+")";ctx.stroke()}}}raf=requestAnimationFrame(drawParticles)}
resizeCanvas();drawParticles();window.addEventListener("resize",resizeCanvas);

// Three.js WebGL hero object: gracefully falls back to CSS orbit if WebGL is unavailable.
(async()=>{try{
 const THREE = await import("three");
 const host=document.createElement("div");host.className="three-host";document.querySelector("#deck").appendChild(host);
 const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:"low-power"});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(host.clientWidth||innerWidth,host.clientHeight||innerHeight);host.appendChild(renderer.domElement);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,(host.clientWidth||innerWidth)/(host.clientHeight||innerHeight),.1,100);camera.position.z=7;
 const group=new THREE.Group();scene.add(group);
 const geometry=new THREE.IcosahedronGeometry(1.45,2),material=new THREE.MeshStandardMaterial({color:0x39cdbb,metalness:.72,roughness:.24,wireframe:true,transparent:true,opacity:.35});
 const mesh=new THREE.Mesh(geometry,material);group.add(mesh);
 const ring=new THREE.Mesh(new THREE.TorusGeometry(2.05,.008,8,180),new THREE.MeshBasicMaterial({color:0x66d9ca,transparent:true,opacity:.45}));ring.rotation.x=1.1;group.add(ring);
 scene.add(new THREE.AmbientLight(0xffffff,.7));const light=new THREE.PointLight(0x52e2ce,4,20);light.position.set(2,3,4);scene.add(light);
 let running=true;const clock=new THREE.Clock();function tick(){if(!running)return;const t=clock.getElapsedTime();group.rotation.y=t*.11;group.rotation.x=Math.sin(t*.22)*.12;mesh.rotation.z=t*.08;renderer.render(scene,camera);requestAnimationFrame(tick)}tick();
 new ResizeObserver(()=>{const w=host.clientWidth||innerWidth,h=host.clientHeight||innerHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(host);
 document.addEventListener("visibilitychange",()=>{running=!document.hidden;if(running)tick()});
 }catch(e){console.info("WebGL indisponible : animation CSS conservée.")}})();
